with open('index.html') as f:
    content = f.read()

changes = 0

old_tonum = 'function toNum(v){ const n = parseFloat(v); return isNaN(n) ? 0 : n; }'
new_tonum = 'function toNum(v){\n  if(v === null || v === undefined || v === \'\') return 0;\n  if(typeof v === \'number\') return isNaN(v) ? 0 : v;\n  // strip currency symbols, thousands separators, and whitespace before parsing,\n  // so "12,000" or "₹1,234.50" parse correctly instead of parseFloat silently\n  // truncating at the first comma (parseFloat(\'12,000\') would otherwise be 12).\n  const cleaned = String(v).replace(/[₹,\\s]/g, \'\');\n  const n = parseFloat(cleaned);\n  return isNaN(n) ? 0 : n;\n}\n'
if old_tonum in content:
    content = content.replace(old_tonum, new_tonum, 1)
    changes += 1

old_fielddefs = "const FIELD_DEFS = [\n  {key:'company', label:'Company', keywords:['company']},\n  {key:'date', label:'Date', keywords:['date']},\n  {key:'billNo', label:'Vch/Bill No', keywords:['vch','bill','voucher']},\n  {key:'retailer', label:'Retailer', keywords:['retailer','party','customer','shop']},\n  {key:'amount', label:'Total Amount', keywords:['amount','total']},\n];"
new_fielddefs = "const FIELD_DEFS = [\n  {key:'company', label:'Company', keywords:['company'], required:true},\n  {key:'date', label:'Date', keywords:['date'], required:true},\n  {key:'billNo', label:'Vch/Bill No', keywords:['vch','bill','voucher'], required:true},\n  {key:'retailer', label:'Retailer', keywords:['retailer','party','customer','shop'], required:true},\n  {key:'amount', label:'Total Amount', keywords:['total amount','total'], required:true},\n  {key:'deliveryDate', label:'Delivery Date', keywords:['delivery date'], required:false},\n  {key:'area', label:'Area', keywords:['area'], required:false},\n  {key:'salesPerson', label:'Sales Person', keywords:['sales person','salesperson'], required:false},\n  {key:'deliveryPartner', label:'Delivery Partner', keywords:['delivery partner','delivery boy'], required:false},\n  {key:'deliveryStatus', label:'Delivery Status', keywords:['delivery status','status'], required:false},\n  {key:'amountAtDelivery', label:'Amount Collected', keywords:['amount collected','collected','received'], required:false},\n  {key:'discount', label:'Discount', keywords:['discount'], required:false},\n  {key:'comments', label:'Comments', keywords:['comment','notes','remark'], required:false},\n];\n\nconst STATUS_CANON = {'cash':'Cash','cancelled':'Cancelled','signed':'Signed','cheque':'Cheque','part delivered':'Part Delivered','upi/bank':'UPI/Bank','upi':'UPI/Bank','bank':'UPI/Bank'};\nfunction canonImportStatus(s){\n  const t = String(s||'').trim();\n  if(!t) return '';\n  return STATUS_CANON[t.toLowerCase()] || t;\n}"
if old_fielddefs in content:
    content = content.replace(old_fielddefs, new_fielddefs, 1)
    changes += 1

old_buildmap = 'function buildMappingUI(){\n  const headers = excelState.headers;\n  const colCount = Math.max(headers.length, 5);\n  const grid = $(\'#mapGrid\');\n  grid.innerHTML = FIELD_DEFS.map((f, idx) => {\n    const options = [];\n    for(let c=0;c<colCount;c++){\n      const h = headers[c];\n      const label = h ? `${colLetter(c)} — ${h}` : `Column ${colLetter(c)}`;\n      options.push({c, label});\n    }\n    // guess: keyword match in header, else positional fallback (idx)\n    let guess = options.find(o => f.keywords.some(k => (headers[o.c]||\'\').toLowerCase().includes(k)));\n    let guessIdx = guess ? guess.c : idx;\n    return `<div class="map-field">\n      <label>${f.label}</label>\n      <select data-target="${f.key}">\n        ${options.map(o=>`<option value="${o.c}" ${o.c===guessIdx?\'selected\':\'\'}>${escapeHtml(o.label)}</option>`).join(\'\')}\n      </select>\n    </div>`;\n  }).join(\'\');\n  $(\'#mappingBox\').style.display = \'block\';\n}'
new_buildmap = 'function buildMappingUI(){\n  const headers = excelState.headers;\n  const colCount = Math.max(headers.length, 5);\n  const grid = $(\'#mapGrid\');\n\n  function renderField(f, idx){\n    const options = [];\n    for(let c=0;c<colCount;c++){\n      const h = headers[c];\n      const label = h ? `${colLetter(c)} — ${h}` : `Column ${colLetter(c)}`;\n      options.push({c, label});\n    }\n    const guess = options.find(o => f.keywords.some(k => (headers[o.c]||\'\').toLowerCase().includes(k)));\n    const notInFile = \'<option value="-1">— not in this file —</option>\';\n    const guessVal = guess ? guess.c : (f.required ? idx : -1);\n    return `<div class="map-field">\n      <label>${f.label}${f.required ? \'\' : \' <span style="opacity:.6;">(optional)</span>\'}</label>\n      <select data-target="${f.key}">\n        ${f.required ? \'\' : notInFile}\n        ${options.map(o=>`<option value="${o.c}" ${o.c===guessVal?\'selected\':\'\'}>${escapeHtml(o.label)}</option>`).join(\'\')}\n      </select>\n    </div>`;\n  }\n\n  const required = FIELD_DEFS.filter(f => f.required);\n  const optional = FIELD_DEFS.filter(f => !f.required);\n  grid.innerHTML =\n    `<div class="map-section-label">Required</div>` +\n    required.map((f,i)=>renderField(f,i)).join(\'\') +\n    `<div class="map-section-label" style="grid-column:1/-1; margin-top:6px;">Optional — only if your file has these</div>` +\n    optional.map((f,i)=>renderField(f,i)).join(\'\');\n  $(\'#mappingBox\').style.display = \'block\';\n}'
if old_buildmap in content:
    content = content.replace(old_buildmap, new_buildmap, 1)
    changes += 1

old_commit = "$('#buildPreviewBtn').addEventListener('click', () => {\n  const mapping = {};\n  $$('#mapGrid select').forEach(sel => { mapping[sel.dataset.target] = parseInt(sel.value,10); });\n\n  const dataRows = excelState.rows.slice(excelState.headerRowIdx + 1);\n  pendingImport = dataRows.map(r => {\n    const company = r[mapping.company];\n    const date = r[mapping.date];\n    const billNo = r[mapping.billNo];\n    const retailer = r[mapping.retailer];\n    const amount = r[mapping.amount];\n    return {\n      id: uid(),\n      company: String(company||'').trim(),\n      date: excelDateFmt(date),\n      billNo: String(billNo||'').trim(),\n      retailer: String(retailer||'').trim(),\n      totalAmount: toNum(String(amount??'0').replace(/[₹,\\s]/g,'')),\n      deliveryDate:'', area:'', salesPerson:'', deliveryPartner:'', deliveryStatus:'',\n      amountAtDelivery:'', comments:'', discount:'',\n      visits: [], nextVisitPlanned:''\n    };\n  }).filter(r => r.company || r.billNo || r.retailer);\n\n  $('#mapInfo').textContent = `${pendingImport.length} rows parsed.`;\n  renderPreview();\n  $('#previewPanel').scrollIntoView({behavior:'smooth', block:'start'});\n});"
new_commit = "$('#buildPreviewBtn').addEventListener('click', () => {\n  const mapping = {};\n  $$('#mapGrid select').forEach(sel => { mapping[sel.dataset.target] = parseInt(sel.value,10); });\n\n  function cell(r, key){\n    const c = mapping[key];\n    return (c === undefined || c === -1) ? '' : r[c];\n  }\n\n  const dataRows = excelState.rows.slice(excelState.headerRowIdx + 1);\n  pendingImport = dataRows.map(r => {\n    return {\n      id: uid(),\n      company: String(cell(r,'company')||'').trim(),\n      date: excelDateFmt(cell(r,'date')),\n      billNo: String(cell(r,'billNo')||'').trim(),\n      retailer: String(cell(r,'retailer')||'').trim(),\n      totalAmount: toNum(cell(r,'amount')),\n      deliveryDate: excelDateFmt(cell(r,'deliveryDate')),\n      area: String(cell(r,'area')||'').trim(),\n      salesPerson: String(cell(r,'salesPerson')||'').trim(),\n      deliveryPartner: String(cell(r,'deliveryPartner')||'').trim(),\n      deliveryStatus: canonImportStatus(cell(r,'deliveryStatus')),\n      amountAtDelivery: cell(r,'amountAtDelivery')==='' ? '' : toNum(cell(r,'amountAtDelivery')),\n      comments: String(cell(r,'comments')||'').trim(),\n      discount: cell(r,'discount')==='' ? '' : toNum(cell(r,'discount')),\n      visits: [], nextVisitPlanned:''\n    };\n  }).filter(r => r.company || r.billNo || r.retailer);\n\n  const extraFieldsUsed = ['deliveryDate','area','salesPerson','deliveryPartner','deliveryStatus','amountAtDelivery','discount','comments']\n    .filter(k => mapping[k] !== -1 && mapping[k] !== undefined);\n  $('#mapInfo').textContent = `${pendingImport.length} rows parsed` + (extraFieldsUsed.length ? ` — including ${extraFieldsUsed.length} extra column${extraFieldsUsed.length===1?'':'s'} beyond the core 5.` : '.');\n  renderPreview();\n  $('#previewPanel').scrollIntoView({behavior:'smooth', block:'start'});\n});"
if old_commit in content:
    content = content.replace(old_commit, new_commit, 1)
    changes += 1

old_renderpreview = 'function renderPreview(){\n  const panel = $(\'#previewPanel\');\n  if(!pendingImport.length){ panel.style.display=\'none\'; return; }\n  panel.style.display = \'block\';\n  $(\'#previewBody\').innerHTML = pendingImport.map(r => `\n    <tr>\n      <td>${escapeHtml(r.company)}</td>\n      <td>${escapeHtml(r.date)}</td>\n      <td>${escapeHtml(r.billNo)}</td>\n      <td>${escapeHtml(r.retailer)}</td>\n      <td class="num">${fmtMoney(r.totalAmount)}</td>\n    </tr>`).join(\'\');\n\n  // duplicate check against existing bills (company+billNo)\n  const existingKeys = new Set(bills.map(b => (b.company+\'|\'+b.billNo).toLowerCase()));\n  const dupes = pendingImport.filter(r => existingKeys.has((r.company+\'|\'+r.billNo).toLowerCase()));\n  const dupBox = $(\'#dupWarnBox\');\n  dupBox.innerHTML = dupes.length\n    ? `<div class="dup-warn">⚠ ${dupes.length} of these rows share a Company + Bill No. with a bill already in the ledger. They\'ll still be added — check for accidental double-paste before continuing.</div>`\n    : \'\';\n}'
new_renderpreview = 'function renderPreview(){\n  const panel = $(\'#previewPanel\');\n  if(!pendingImport.length){ panel.style.display=\'none\'; return; }\n  panel.style.display = \'block\';\n\n  const hasExtra = pendingImport.some(r => r.deliveryDate || r.area || r.salesPerson || r.deliveryPartner || r.deliveryStatus || r.amountAtDelivery !== \'\' || r.discount !== \'\' || r.comments);\n\n  $(\'#previewHead\').innerHTML = `<tr>\n    <th>Company</th><th>Date</th><th>Vch/Bill No</th><th>Retailer</th><th class="num">Total Amount</th>\n    ${hasExtra ? \'<th>Delivery Date</th><th>Sales Person</th><th>Delivery Partner</th><th>Delivery Status</th>\' : \'\'}\n  </tr>`;\n\n  $(\'#previewBody\').innerHTML = pendingImport.map(r => `\n    <tr>\n      <td>${escapeHtml(r.company)}</td>\n      <td>${escapeHtml(r.date)}</td>\n      <td>${escapeHtml(r.billNo)}</td>\n      <td>${escapeHtml(r.retailer)}</td>\n      <td class="num">${fmtMoney(r.totalAmount)}</td>\n      ${hasExtra ? `<td>${escapeHtml(r.deliveryDate)}</td><td>${escapeHtml(r.salesPerson)}</td><td>${escapeHtml(r.deliveryPartner)}</td><td>${escapeHtml(r.deliveryStatus)}</td>` : \'\'}\n    </tr>`).join(\'\');\n\n  // duplicate check against existing bills (company+billNo)\n  const existingKeys = new Set(bills.map(b => (b.company+\'|\'+b.billNo).toLowerCase()));\n  const dupes = pendingImport.filter(r => existingKeys.has((r.company+\'|\'+r.billNo).toLowerCase()));\n  const dupBox = $(\'#dupWarnBox\');\n  dupBox.innerHTML = dupes.length\n    ? `<div class="dup-warn">⚠ ${dupes.length} of these rows share a Company + Bill No. with a bill already in the ledger. They\'ll still be added — check for accidental double-paste before continuing.</div>`\n    : \'\';\n}'
if old_renderpreview in content:
    content = content.replace(old_renderpreview, new_renderpreview, 1)
    changes += 1

old_thead = '          <thead><tr><th>Company</th><th>Date</th><th>Vch/Bill No</th><th>Retailer</th><th class="num">Total Amount</th></tr></thead>\n          <tbody id="previewBody"></tbody>'
new_thead = '          <thead id="previewHead"><tr><th>Company</th><th>Date</th><th>Vch/Bill No</th><th>Retailer</th><th class="num">Total Amount</th></tr></thead>\n          <tbody id="previewBody"></tbody>'
if old_thead in content:
    content = content.replace(old_thead, new_thead, 1)
    changes += 1

old_css = '  .map-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:12px; margin-top:14px;}'
new_css = '  .map-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(180px,1fr)); gap:12px; margin-top:14px;}\n  .map-section-label{grid-column:1/-1; font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--ink-soft); margin-top:4px;}'
if old_css in content:
    content = content.replace(old_css, new_css, 1)
    changes += 1

if changes == 7:
    with open('index.html', 'w') as f:
        f.write(content)
    print("SUCCESS: full-column import upgrade applied.")
elif changes == 0:
    print("NOTHING MATCHED: file may already be upgraded, or differs from expected.")
else:
    print(f"PARTIAL: only {changes} of 7 patches applied -- file NOT saved. Send this output back.")
